"""Saved-voyage startup regression. The private input backup is never bundled or logged."""
import argparse,json,time,hashlib,unittest
from pathlib import Path
from test_boot_hotfix import BootHotfix
from test_continuity import RecordedResult
BACKUP=None
class StartupSize(BootHotfix):
 def existing(self):
  p=self.raw_page();self.failures_http=[];self.console_errors=[];self.requests=[]
  def response(r):
   if r.status>=400:self.failures_http.append({'status':r.status,'operation':r.url.split(self.url)[-1]})
   if r.request.method=='POST' and r.url.endswith('/api/icarus/host/publish'):self.requests.append({'status':r.status,'bytes':len((r.request.post_data or '').encode())})
  p.on('response',response);p.on('console',lambda m:self.console_errors.append(m.text) if m.type=='error' else None);p.goto(self.url+'/icarus.html?icarus_soak=1');p.wait_for_function('ICARUSBoot.complete&&ICARUSHost.canWrite()');p.locator('.boot-observe').click();p.on('dialog',lambda d:d.accept());p.locator('#backupfile').set_input_files(str(BACKUP));p.wait_for_function('tick=>__icarusSoak.time()===tick&&!ICARUSBackupUI.busy()',arg=self.original['state']['tick']);p.evaluate('ICARUSDurable.flush()');return p
 def setUp(self):
  super().setUp()
  if not BACKUP:self.skipTest('Supply --backup to test an existing voyage')
  self.original=json.loads(BACKUP.read_text())
 def history(self,p):return p.evaluate('ICARUSDurable.history()')
 def test_size_existing_user_world_restart_keeps_crew_maps_history_and_every_recording(self):
  p=self.existing();expected=self.original['state'];p.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("LINKED")');s=p.evaluate('__icarusSoak.snapshot()');self.assertTrue(s['crew']==expected['crew'],'Saved crew differs from supplied backup');self.assertTrue(s['world']['asteroidExploration']==expected['asteroidExploration'],'Saved asteroid differs from supplied backup');self.assertTrue(s['droneOperations']==expected['droneOperations'],'Saved drones/recordings differ from supplied backup');self.assertTrue(s['knowledge']==expected['knowledge'],'Saved knowledge differs from supplied backup');self.assertTrue(s['fieldEvidence']==expected['fieldEvidence'],'Saved field recordings differ from supplied backup');stored={r['id']:r for r in self.history(p)};self.assertTrue(all(stored.get(r['id'])==r for r in self.original['history']),'An original source history record was lost or modified');history_before=self.history(p);p.reload();p.wait_for_function('ICARUSBoot.complete&&ICARUSHost.canWrite()');p.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("LINKED")');p.wait_for_timeout(1800);after=p.evaluate('__icarusSoak.snapshot()');self.assertTrue(after==s,'Restart changed domains: '+','.join(k for k in s if s[k]!=after[k]));self.assertTrue(p.locator('#icarus-boot').is_visible());self.assertIn('ICARUS ONLINE',p.locator('.boot-status').inner_text());self.assertFalse(any(r['status']==413 for r in self.failures_http));self.assertTrue(all(r['status']==200 and r['bytes']<=110000 for r in self.requests));self.assertTrue(self.history(p)==history_before,'Restart changed the retained full source archive');p.locator('.boot-observe').click();self.assertTrue(p.locator('#icarus-boot').is_hidden());self.assertEqual(p.evaluate('__icarusSoak.snapshot()'),s)
 def test_size_record_frames_load_on_selection_and_never_mutate_saved_media(self):
  p=self.existing();p.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("LINKED")');before=p.evaluate('__icarusSoak.snapshot().droneOperations');p.evaluate('''()=>{window.recordReads=0;const original=ICARUSDroneOps.receivedRecord;ICARUSDroneOps.receivedRecord=(...a)=>{window.recordReads++;return original(...a);};}''');p.wait_for_timeout(1400);self.assertEqual(p.evaluate('recordReads'),0);p.locator('#icarus-menu button[data-page="missions"]').click();p.locator('#page-missions [data-subtab="active"]').click();p.locator('.drone-ops details').nth(2).locator('summary').click();available=[c for c in before['archive'][-8:] if c['frames'][0].get('image')];self.assertTrue(available,'Saved world must include genuine retained captured frames');record=available[0];p.locator('.drone-record').select_option(record['id']);p.wait_for_function('recordReads>0');p.wait_for_function('document.querySelector(".drone-record-label").textContent.includes("CAPTURED PROCEDURAL FRAME")');self.assertEqual(int(p.locator('.drone-frame').get_attribute('max')),len(record['frames'])-1);self.assertTrue(p.evaluate('__icarusSoak.snapshot().droneOperations')==before,'Recording playback altered saved drone state')
 def test_size_payload_rejection_is_not_a_writer_failure_and_reports_exact_operation(self):
  p=self.existing();p.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("LINKED")');before=p.evaluate('__icarusSoak.snapshot()');p.route('**/api/icarus/host/publish',lambda r:r.fulfill(status=413,content_type='application/json',body='{"error":"Controlled telemetry-size rejection"}'));p.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("TELEMETRY PREVIEW ERROR")');self.assertTrue(p.evaluate('ICARUSHost.canWrite()&&ICARUSDurable.canWrite()'));self.assertEqual(p.evaluate('__icarusSoak.snapshot()'),before);p.unroute('**/api/icarus/host/publish');p.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("LINKED")');code,d=self.req('/api/icarus/host/publish',{'telemetry':{'padding':'x'*132000}},{'X-Icarus-Key':'test-host'});self.assertEqual(code,413);self.assertEqual(d['operation'],'/api/icarus/host/publish');self.assertEqual(d['limitBytes'],131072);self.assertGreater(d['receivedBytes'],d['limitBytes']);self.assertEqual(p.evaluate('__icarusSoak.snapshot()'),before)
 def test_size_paired_terminal_receives_existing_world_without_stream_size_failure(self):
  p=self.existing();p.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("LINKED")');before=p.evaluate('__icarusSoak.snapshot()');phone=self.page(width=390,height=844);self.tab(phone,'icarus');phone.wait_for_function('document.querySelector("#icarusLink").textContent.includes("tick 46035")');phone.wait_for_timeout(2000);self.assertEqual(phone.evaluate('typeof __icarusSoak'),'undefined');self.assertIn('limited remote history preview',phone.locator('.op-status').inner_text());self.assertEqual(p.evaluate('__icarusSoak.snapshot()'),before);self.assertTrue(p.evaluate('ICARUSHost.canWrite()'));self.assertFalse(any(r['status']==413 for r in self.failures_http))

