 names=[n for n in unittest.defaultTestLoader.getTestCaseNames(StartupSize) if n.startswith('test_size_')];r=unittest.TextTestRunner(verbosity=2,resultclass=RecordedResult).run(unittest.TestSuite(StartupSize(n) for n in names));a.report.parent.mkdir(parents=True,exist_ok=True);a.report.write_text(json.dumps({'passed':r.wasSuccessful(),'tests_run':r.testsRun,'passed_cases':r.successes,'backup_sha256':hashlib.sha256(BACKUP.read_bytes()).hexdigest(),'input_is_private_and_not_bundled':True,'failures':[{'test':str(t),'detail':d[:6000]} for t,d in r.failures],'errors':[{'test':str(t),'detail':d[:6000]} for t,d in r.errors]},indent=2));raise SystemExit(not r.wasSuccessful())
